using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BattleActionToEnemyWithLowestCorruptionOmenLogic", menuName = "Data/Battle/Omens System/Omen Logic/BattleActionToEnemyWithLowestCorruption Omen Logic")]
public class BattleActionToEnemyWithLowestCorruptionOmenLogic : OmenLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private bool directPurify;

	public override void ActivateOmen(BattleAction battleAction, int actionValue, GameObject target, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		if (currentCorruptedAnimals.activeCorruptedAnimals.Count == 0)
		{
			return;
		}
		GameObject enemyWithLowestCorruption = currentCorruptedAnimals.GetEnemyWithLowestCorruption();
		if (!(enemyWithLowestCorruption == null))
		{
			if (directPurify)
			{
				enemyWithLowestCorruption.GetComponent<CorruptionStats>().Purify(actionValue, source, corruptionPurifyModifierEnum, playSFX);
			}
			else
			{
				battleAction.CastTargetAmount(enemyWithLowestCorruption, actionValue, source);
			}
		}
	}
}
